import { accountApi, discoverAccountConfig } from './account.js';
import { toDataURL } from './vendor/qr.js';
import { consumeQuickQuizAuthIntent, saveQuickQuizAuthIntent } from './quick-quiz-auth-intent.js';
import { answerDeadline, deadlineForPhase, normalizeQuizPhase, rankFor } from './quick-quiz-model.js';

const app = document.querySelector('#quick-quiz-app');
const query = new URLSearchParams(location.search);
const authIntent = consumeQuickQuizAuthIntent();
const state = { roomId: query.get('room'), invite: query.get('invite'), token: '', host: query.get('create') === '1' || query.has('venue'), data: null, name: authIntent?.name || '', levelId: authIntent?.difficulty || 'beginner', error: '', busy: false, loading: false, terminal: false, pollTimer: 0, pollDelay: 1000, lastKey: '', requestEpoch: 0, timer: 0, clock: null };
const esc = (v) => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const storageKey = id => `mingle.quick-quiz.room:${id}`;
const joinKey = id => `mingle.quick-quiz.join:${id || 'pending'}`;
const secret = () => { const b = new Uint8Array(32); crypto.getRandomValues(b); return btoa(String.fromCharCode(...b)).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,''); };
function save() { try { sessionStorage.setItem(storageKey(state.roomId), JSON.stringify({ roomId: state.roomId, invite: state.invite, token: state.token, host: state.host })); } catch {} }
function restore() { try { const v = JSON.parse(sessionStorage.getItem(storageKey(state.roomId)) || 'null'); if (v?.token) { state.token = v.token; state.invite ||= v.invite || ''; state.host = v.host === true || state.host; } } catch {} }
function shell(content) { app.innerHTML = `<div class="quick-quiz-shell"><header class="quick-quiz-brand"><img src="/assets/mingle-cards-masthead.png" alt="Mingle.Cards"><a href="/">トップへ戻る</a></header>${content}</div>`; }
function message() { return state.error ? `<p class="quick-quiz-error" role="alert">${esc(state.error)}</p>` : ''; }
const levels = [['beginner','初級'],['intermediate','中級'],['advanced','上級'],['expert','特級']];
function createView() { shell(`<section class="quick-quiz-card"><h1>みんなで早押しクイズ！</h1><p class="quick-quiz-lead">問題を見て、わかった人から早押し。正解数で競います。</p><p class="quick-quiz-muted">2〜8人・全6問。正解で1点。間違えると、その問題はおやすみ。代表者がルームを作り、参加者はQRまたはURLから参加します。</p><form class="quick-quiz-form" data-create><label>呼び名<input name="name" required maxlength="20" autocomplete="nickname" value="${esc(state.name)}"></label><fieldset><legend>難易度</legend><div class="quick-quiz-levels">${levels.map(([id,label]) => `<label><input type="radio" name="level" value="${id}" ${state.levelId===id?'checked':''}><span><strong>${label}</strong><small>4択・6問</small></span></label>`).join('')}</div></fieldset><div class="quick-quiz-actions"><button class="primary-button" type="submit" ${state.busy?'disabled':''}>${state.busy?'作成中…':'ルームを作る'}</button></div>${message()}</form></section>`); }
function joinView() { shell(`<section class="quick-quiz-card"><h1>クイズに参加</h1><p class="quick-quiz-lead">呼び名を入力すると、みんなの問題が見えます。</p><form class="quick-quiz-form" data-join><label>呼び名<input name="name" required maxlength="20" autocomplete="nickname" value="${esc(state.name)}"></label><button class="primary-button" type="submit" ${state.busy?'disabled':''}>${state.busy?'参加中…':'参加する'}</button>${message()}</form></section>`); }
function roomOf(data) { return data?.room || {}; }
function gameOf(data) { return data?.quizBuzz || {}; }
function phaseOf(g, room) { return normalizeQuizPhase(g, room); }
function membersOf(data) { return roomOf(data).members || data?.members || []; }
function qrBlock() { const url = `${location.origin}/quick-quiz-room.html?room=${encodeURIComponent(state.roomId)}&invite=${encodeURIComponent(state.invite || '')}`; return `<div class="quick-quiz-qr"><img data-qr alt="参加用QRコード"><label>参加用URL<input readonly value="${esc(url)}" aria-label="参加用URL"></label><button class="secondary-button" type="button" data-copy>URLをコピー</button><small>QRが表示できないときはURLを渡してください</small></div>`; }
function lobby(data) { const ms = membersOf(data); const host = data.host === true || state.host; const canStart = ms.length >= 2 && ms.length <= 8; return `<div class="quick-quiz-status"><span>参加者 ${ms.length} / 8人</span><span>開始前</span></div><h1>みんなで集まろう</h1><p class="quick-quiz-lead">${ms.length < 2 ? 'あと1人参加すると始められます。' : 'そろったら代表者がスタートします。'}</p><ul class="quick-quiz-scoreboard">${ms.map(m=>`<li><span>${esc(m.name)}${m.role==='host'?'（代表者）':''}</span></li>`).join('')}</ul>${host ? `<button class="primary-button" data-act="start" ${!canStart||state.busy?'disabled':''}>${state.busy?'開始中…':'クイズを始める'}</button>${qrBlock()}` : '<p class="quick-quiz-wait">代表者が開始するまでお待ちください。</p>'}${message()}`; }
function scores(g, ms) { const src = Array.isArray(g.scores) ? g.scores : Object.entries(g.scores || {}).map(([id,score])=>({id,score})); return src.map(x => ({ id:x.id||x.memberId, name:x.name || ms.find(m=>m.id===(x.id||x.memberId))?.name || '参加者', score:Number(x.score||0) })).sort((a,b)=>b.score-a.score); }
function roundOf(g) { return g.round || g.currentRound || {}; }
function questionText(g) { return roundOf(g).question || '問題を読み込み中…'; }
function choices(g) { return (roundOf(g).choices || []).map((x) => ({ id: String(x.id), label: x.text || '' })); }
function currentId(data) { return data.member?.id || ''; }
function gameView(data) {
  const g=gameOf(data), r=roundOf(g), ms=membersOf(data), phase=phaseOf(g,roomOf(data)), me=currentId(data), who=r.winnerMemberId || null, locked=Array.isArray(r.lockedMemberIds) ? r.lockedMemberIds : [], isLocked=locked.includes(me), revealed=phase==='reveal', n=Math.min(6,Math.max(1,Number(g.questionIndex||0)+1)), total=Number(g.totalQuestions||6), opts=choices(g), claimedByMe=String(r.claimId||'') !== '', canBuzz=!claimedByMe&&!isLocked&&!revealed&&phase==='question', canAnswer=claimedByMe&&!isLocked&&!revealed;
  if (phase==='ended') { const rows=scores(g,ms); return `<div class="quick-quiz-summary"><h1>結果</h1><p class="quick-quiz-lead">おつかれさまでした。</p><ol class="quick-quiz-scoreboard">${rows.map((r,i)=>`<li><span>${rankFor(rows,i)}位 ${esc(r.name)}</span><strong>${r.score}点</strong></li>`).join('')}</ol><a class="primary-button" href="/">トップへ戻る</a></div>`; }
  const correct=r.correctChoiceId||g.correctChoiceId||g.correctOptionId; const attempt=r.lastAttempt||{}; const result=attempt.result||attempt.outcome||attempt.status||g.result||g.outcome||''; const winnerName=r.winnerMemberId ? ms.find(m=>m.id===r.winnerMemberId)?.name : ''; const status=revealed ? (result==='correct'?'正解！':result==='timeout'?'時間切れ':result==='wrong'?'不正解':winnerName?`回答者：${esc(winnerName)} が正解`:'答えが発表されました') : state.busy ? '判定中…' : claimedByMe ? 'あなたが回答者です。選択肢を選んでください。' : who ? `回答者：${esc(ms.find(m=>m.id===who)?.name||'決定済み')}` : (isLocked?(result==='timeout'?'時間切れ。この問題はおやすみ。':result==='wrong'?'不正解。この問題はおやすみ。':'この問題では回答できません。次の問題を待っています。'):'わかったら早押し！');
  const deadline = deadlineForPhase(g, roomOf(data)); const serverNow=Date.parse(g.serverNow||''); const remaining=deadline?Math.max(0,Math.ceil((Date.parse(deadline)-(Number.isFinite(serverNow)?serverNow:Date.now()))/1000)):null;
  const wait=isLocked&&!revealed?'この問題の回答権はありません。次の問題を待っています。':'';
  return `<div class="quick-quiz-status"><span>第${n} / ${total}問</span><span>${status}<span data-countdown>${remaining!==null?` · 残り${remaining}秒`:''}</span></span></div><h1 class="quick-quiz-question">${esc(questionText(g))}</h1><div class="quick-quiz-options">${opts.map(o=>{const correctChoice=revealed&&String(o.id)===String(correct);return `<button type="button" data-choice="${esc(o.id)}" ${canAnswer?'':'disabled'} ${correctChoice?'class="is-correct"':''}>${correctChoice?'正解：':''}${esc(o.label)}</button>`}).join('')}</div>${canBuzz?`<button class="quick-quiz-buzz" data-act="claim" ${state.busy?'disabled':''}>${state.busy?'判定中…':'早押しする'}</button>`:''}${wait?`<p class="quick-quiz-wait">${wait}</p>`:''}${revealed&&r.explanation?`<p class="quick-quiz-note">${esc(r.explanation)}</p>`:''}<ol class="quick-quiz-scoreboard">${scores(g,ms).map((row,i)=>`<li><span>${rankFor(scores(g,ms),i)}位 ${esc(row.name)}</span><strong>${row.score}点</strong></li>`).join('')}</ol>${message()}`; }
function syncTimer(g, phase) { clearInterval(state.timer); const deadline=deadlineForPhase(g); if(!deadline)return; if(state.clock?.deadline===deadline){ state.timer=setInterval(()=>{const node=app.querySelector('[data-countdown]');if(!node)return;const now=state.clock.serverMs+(performance.now()-state.clock.perf);const left=Math.max(0,Math.ceil((Date.parse(deadline)-now)/1000));node.textContent=` · 残り${left}秒`;},250); return; } const serverMs=Date.parse(g.serverNow||''); state.clock={deadline,serverMs:Number.isFinite(serverMs)?serverMs:Date.now(),perf:performance.now()}; state.timer=setInterval(()=>{const node=app.querySelector('[data-countdown]');if(!node)return;const now=state.clock.serverMs+(performance.now()-state.clock.perf);const left=Math.max(0,Math.ceil((Date.parse(deadline)-now)/1000));node.textContent=` · 残り${left}秒`;},250); }
function render(data) { const room=roomOf(data), g=gameOf(data), r=roundOf(g), phase=phaseOf(g,room), key=JSON.stringify([room.revision,room.status,phase,g.questionNo,g.questionIndex,r.phase,r.claimId,r.winnerMemberId,membersOf(data).map(m=>m.id),state.busy,state.error]); if(key===state.lastKey&&!state.error)return; state.lastKey=key; shell(`<section class="quick-quiz-card">${phase==='lobby'?lobby(data):gameView(data)}</section>`); syncTimer(g,phase); if(phase==='lobby'&&state.host){const u=`${location.origin}/quick-quiz-room.html?room=${encodeURIComponent(state.roomId)}&invite=${encodeURIComponent(state.invite||'')}`;toDataURL(u,{margin:4,width:160}).then(v=>{const i=app.querySelector('[data-qr]');if(i?.isConnected)i.src=v;}).catch(()=>{});app.querySelector('[data-copy]')?.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(u);state.error='URLをコピーしました。';render(data);}catch{state.error='コピーできませんでした。';render(data);}});}}
function currentRevision(){return roomOf(state.data).revision ?? gameOf(state.data).revision;}
async function act(action,payload={}) { if(state.busy||!state.data)return; state.busy=true; state.error=''; render(state.data); const epoch=++state.requestEpoch; let stale=false; try{state.data=await accountApi.quickQuizAction(state.roomId,state.token,action,currentRevision(),payload);state.lastKey='';}catch(e){if(e?.status===409){state.error='進行が更新されています。最新状態を読み込みます。';stale=true;}else{state.error='操作を反映できませんでした。通信を確認して再試行してください。';}}finally{state.busy=false; if(epoch===state.requestEpoch){render(state.data); if(stale)await load(); else schedule();}}}
async function load(){if(!state.roomId||!state.token||state.busy||state.loading||state.terminal)return;state.loading=true;const epoch=state.requestEpoch;try{const data=await accountApi.groupState(state.roomId,state.token);if(epoch!==state.requestEpoch)return;state.data=data;state.host=data.host===true||state.host;state.error='';state.terminal=false;state.pollDelay=1000;render(data);}catch(e){const status=Number(e?.status);if([401,403].includes(status)){state.token='';state.data=null;joinView();}else if([404,410].includes(Number(e?.status))){state.terminal=true;state.error='このルームは終了または期限切れです。';terminalView();}else{state.error=status===409?'進行が更新されています。再読み込みします。':'通信できません。接続を確認して再試行してください。';if(state.data)render(state.data);else terminalView();state.pollDelay=status===409?300:Math.min(15000,state.pollDelay*2);}}finally{state.loading=false;schedule();}}
function schedule(){clearTimeout(state.pollTimer);if(!state.terminal&&state.roomId&&state.token&&!state.busy&&!state.loading&&!document.hidden&&navigator.onLine&&(!state.data||!['ended','finished'].includes(phaseOf(gameOf(state.data),roomOf(state.data)))))state.pollTimer=setTimeout(load,state.pollDelay);}
function terminalView(){shell(`<section class="quick-quiz-card"><h1>ルームを表示できません</h1>${message()}${state.roomId&&state.token?'<button class="primary-button" data-act="retry">再試行</button>':''}<a class="primary-button" href="/quick-quiz-room.html?create=1">新しいルームを作る</a></section>`);}
app.addEventListener('submit',async e=>{e.preventDefault();const f=e.target;if(state.busy)return;state.name=String(new FormData(f).get('name')||'').trim();if(f.matches('[data-create]'))state.levelId=String(new FormData(f).get('level')||'beginner');state.busy=true;render(state.data||{});try{let r;if(f.matches('[data-create]')){r=await accountApi.createQuickQuizRoom(state.name,state.levelId,query.get('venue')||'');state.host=true;}else{let s;try{s=sessionStorage.getItem(joinKey(state.roomId))||secret();sessionStorage.setItem(joinKey(state.roomId),s);}catch{s=secret();}r=await accountApi.joinGroupRoom(state.roomId,state.invite,state.name,false,s,false);}state.roomId=r.room.id;state.invite=r.inviteToken||state.invite;state.token=r.memberToken;state.data=r;save();history.replaceState({},'',`/quick-quiz-room.html?room=${encodeURIComponent(state.roomId)}&invite=${encodeURIComponent(state.invite||'')}`);state.error='';}catch(e){if(f.matches('[data-create]')&&Number(e?.status)===401){saveQuickQuizAuthIntent({venueToken:query.get('venue')||'',name:state.name,difficulty:state.levelId});location.assign('/?quickQuizAuth=1');return;}state.error=Number(e?.status)===401?'ルーム作成にはログインが必要です。':'参加できませんでした。入力と招待URLを確認してください。';}finally{state.busy=false;renderCurrent();schedule();}});
app.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.act==='retry'){load();return;}const g=gameOf(state.data),r=roundOf(g);if(b.dataset.choice!==undefined)act('answer',{choiceId:b.dataset.choice,roundNo:Number(g.roundNo||1),questionId:r.questionId||'',claimId:r.claimId||''});else if(b.dataset.act)act(b.dataset.act,b.dataset.act==='claim'?{roundNo:Number(g.roundNo||1),questionId:r.questionId||''}:{});});
function renderCurrent(){if(state.data)render(state.data);else if(state.terminal)terminalView();else state.host?createView():joinView();}
document.addEventListener('visibilitychange',()=>{if(!document.hidden){load();schedule();}else clearTimeout(state.pollTimer);});window.addEventListener('online',()=>{load();schedule();});
await discoverAccountConfig();restore();if(state.roomId&&state.token)load();else if(state.roomId&&!state.host){try{await accountApi.previewGroupRoom(state.roomId,state.invite);joinView();}catch{state.error='このルームは見つかりません。';joinView();}}else if(state.host)createView();else terminalView();









